//! Conversion and Dockerfile rendering for validated custom definitions.
use super::definition::*;
use crate::data::config::agent_definition::{
    load_agent_definition_with_scope, DeliveryKind, LoadedAgentDefinition, ModelFlagSpec,
    SeedPromptSpec,
};
use crate::engine::error::EngineError;

pub const DOCKERFILE_HEADER_PREFIX: &str = "# awman-generated from ";
pub const DOCKERFILE_HEADER_LINE_2: &str =
    "# Edit the agent definition and re-run `awman ready`; do not edit this file.";

pub fn convert(
    loaded: &LoadedAgentDefinition,
    name: &str,
    scope: DefinitionScope,
) -> AgentDefinition {
    let file = &loaded.file;
    let prompt = file.system_prompt.as_ref();
    let image = match &loaded.dockerfile {
        Some((path, _)) => AgentImageSource::UserDockerfile { path: path.clone() },
        None => AgentImageSource::Rendered {
            spec: ImageSpec {
                needs_node: file.image.needs_node,
                apt: file.image.apt.clone(),
                install: file.image.install.clone(),
                binary: file.smoke_binary(),
            },
        },
    };
    AgentDefinition {
        name: name.into(),
        display_name: file.display_name.clone(),
        homepage: file.homepage.clone(),
        origin: AgentOrigin::Custom {
            scope,
            path: loaded.path.clone(),
            sha256: loaded.sha256.clone(),
        },
        image,
        interactive_entrypoint: file.run.command.clone(),
        non_interactive_flag: file.run.non_interactive.clone(),
        headless_prompt_in_argv: false,
        output_format: file.run.output_format,
        interactive_only_flags: file.run.interactive_only_flags.clone(),
        plan_flags: file.modes.plan.clone(),
        yolo_flags: file.modes.yolo.clone(),
        auto_flags: file.modes.auto.clone(),
        disallowed_tools_flag: file.tools.as_ref().and_then(|t| t.disallowed_flag.clone()),
        allowed_tools_flag: file.tools.as_ref().and_then(|t| t.allowed_flag.clone()),
        model_flag: match file.run.model {
            ModelFlagSpec::Space => ModelFlagDelivery::SpaceArg,
            ModelFlagSpec::Equals => ModelFlagDelivery::EqArg,
            ModelFlagSpec::Unsupported => ModelFlagDelivery::Unsupported,
        },
        interactive_seed_delivery: match &file.run.seed_prompt {
            SeedPromptSpec::Keyword(_) => InteractiveSeedDelivery::Positional,
            SeedPromptSpec::Flag { flag } => InteractiveSeedDelivery::Flag(flag.clone()),
        },
        supports_stdin_injection: false,
        supports_acp: file.acp.is_some(),
        acp_entrypoint: file.acp.as_ref().map(|a| a.command.clone()),
        system_prompt_delivery: match prompt.map(|p| p.delivery).unwrap_or_default() {
            DeliveryKind::AppendFile => SystemPromptMode::Append,
            DeliveryKind::AppendInline => SystemPromptMode::AppendInline {
                key: prompt.and_then(|p| p.key.clone()).unwrap_or_default(),
            },
            DeliveryKind::Replace => SystemPromptMode::Replace,
            DeliveryKind::AgentsMd => SystemPromptMode::AgentsMd,
            DeliveryKind::EnvFile => SystemPromptMode::EnvFile {
                var: prompt.and_then(|p| p.env.clone()).unwrap_or_default(),
            },
            DeliveryKind::AddDir => SystemPromptMode::AddDir {
                flag: prompt.and_then(|p| p.flag.clone()).unwrap_or_default(),
            },
            DeliveryKind::None => SystemPromptMode::Unsupported,
        },
        system_prompt_flag: prompt.and_then(|p| p.flag.clone()),
        sbx_kit_kind: SbxKitKind::Agent,
        settings_mount: file
            .settings
            .as_ref()
            .and_then(|s| s.host_dir.clone())
            .map(SettingsMount::Direct)
            .unwrap_or(SettingsMount::None),
        extra_settings_mounts: Vec::new(),
        session_storage_dirs: Vec::new(),
        skills_mount: file.settings.as_ref().and_then(|s| s.skills_dir.clone()),
        credential_source: CredentialSource::None,
        ping_argv: file.ping.as_ref().map(|p| p.command.clone()),
        static_env: file
            .run
            .env
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect(),
        auth_env: file
            .auth
            .as_ref()
            .map(|a| a.env.clone())
            .unwrap_or_default(),
        sandbox_permission_mode_supported: false,
        sandbox_model_note: None,
        sandbox_auth_env_vars: vec![],
        deprecation_note: None,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RenderedDockerfile {
    pub content: String,
    pub warnings: Vec<String>,
}

pub fn dockerfile_template() -> &'static str {
    include_str!("../../../templates/Dockerfile.custom")
}

pub fn rendered_header(def: &AgentDefinition) -> String {
    match &def.origin {
        AgentOrigin::Custom {
            scope,
            path,
            sha256,
        } => format!(
            "{DOCKERFILE_HEADER_PREFIX}{}:{} — definition sha256: {sha256}\n{DOCKERFILE_HEADER_LINE_2}",
            scope.as_str(),
            path.display()
        ),
        AgentOrigin::FirstParty => String::new(),
    }
}

pub fn header_hash(existing: &str) -> Option<String> {
    existing
        .lines()
        .next()?
        .strip_prefix(DOCKERFILE_HEADER_PREFIX)?
        .rsplit_once(" — definition sha256: ")
        .map(|(_, hash)| hash.to_string())
}

pub fn render_dockerfile(
    def: &super::ResolvedAgent,
    project_tag: &str,
) -> Result<RenderedDockerfile, EngineError> {
    let mut warnings = Vec::new();
    let content = match &def.image {
        AgentImageSource::Download => {
            return Err(EngineError::AgentDefinitionInvalid {
                path: std::path::PathBuf::from(&def.name),
                problems: vec!["first-party Dockerfiles must be provisioned by download".into()],
            });
        }
        AgentImageSource::Rendered { spec } => {
            let apt = if spec.apt.is_empty() {
                String::new()
            } else {
                format!(
                    "RUN apt-get update && apt-get install -y --no-install-recommends {} && rm -rf /var/lib/apt/lists/*",
                    spec.apt.join(" ")
                )
            };
            let install = spec
                .install
                .iter()
                .map(|s| {
                    format!(
                        "RUN {}",
                        serde_json::to_string(&["/bin/bash", "-eo", "pipefail", "-c", s.as_str()])
                            .expect("strings serialize")
                    )
                })
                .collect::<Vec<_>>()
                .join("\n");
            // Replace template placeholders in one pass: an install command containing
            // placeholder-looking text is user content, not another template.
            let values = [
                ("{{AWMAN_HEADER}}", rendered_header(def)),
                ("{{AWMAN_BASE_IMAGE}}", project_tag.into()),
                (
                    "{{AWMAN_NODE_BLOCK}}",
                    if spec.needs_node {
                        NODE_BLOCK.into()
                    } else {
                        String::new()
                    },
                ),
                ("{{AWMAN_APT_BLOCK}}", apt),
                ("{{AWMAN_INSTALL_BLOCK}}", install),
                (
                    "{{AWMAN_BINARY}}",
                    shell_words::quote(&spec.binary).into_owned(),
                ),
            ];
            let mut content = String::new();
            for line in dockerfile_template().split_inclusive('\n') {
                let mut remaining = line;
                while let Some((offset, (key, value))) = values
                    .iter()
                    .filter_map(|pair| remaining.find(pair.0).map(|offset| (offset, pair)))
                    .min_by_key(|(offset, _)| *offset)
                {
                    content.push_str(&remaining[..offset]);
                    content.push_str(value);
                    remaining = &remaining[offset + key.len()..];
                }
                content.push_str(remaining);
            }
            content
        }
        AgentImageSource::UserDockerfile { .. } => {
            let AgentOrigin::Custom {
                scope,
                path,
                sha256,
            } = &def.origin
            else {
                unreachable!("custom Dockerfile requires custom origin")
            };
            // Re-check containment and symlinks before copying. Reject edits between
            // approval/resolve and rendering rather than copying unapproved bytes.
            let loaded = load_agent_definition_with_scope(path, *scope)?;
            if loaded.sha256 != *sha256 {
                return Err(EngineError::AgentDefinitionInvalid { path: path.clone(), problems: vec!["definition or Dockerfile changed during launch; resolve and approve it again".into()] });
            }
            let (_, bytes) =
                loaded
                    .dockerfile
                    .ok_or_else(|| EngineError::AgentDefinitionInvalid {
                        path: path.clone(),
                        problems: vec!["image.dockerfile is no longer set".into()],
                    })?;
            let source =
                String::from_utf8(bytes).map_err(|e| EngineError::AgentDefinitionInvalid {
                    path: path.clone(),
                    problems: vec![format!("image.dockerfile must be UTF-8: {e}")],
                })?;
            if !source.lines().any(|line| {
                line.trim().strip_prefix("FROM ").is_some_and(|rest| {
                    rest.split_whitespace().next() == Some("{{AWMAN_BASE_IMAGE}}")
                })
            }) {
                warnings.push(format!("{}: no FROM {{{{AWMAN_BASE_IMAGE}}}}; the project image will not be layered underneath", path.display()));
            }
            format!(
                "{}\n{}",
                rendered_header(def),
                source.replace("{{AWMAN_BASE_IMAGE}}", project_tag)
            )
        }
    };
    Ok(RenderedDockerfile { content, warnings })
}

const NODE_BLOCK: &str = "RUN rm -rf /var/lib/apt/lists/* \\\n    && apt-get clean \\\n    && apt-get update \\\n    && apt-get install -y --no-install-recommends gnupg \\\n    && curl -fsSL --retry 5 --retry-delay 2 --retry-max-time 60 https://deb.nodesource.com/setup_20.x | bash - \\\n    && apt-get install -y --no-install-recommends nodejs \\\n    && rm -rf /var/lib/apt/lists/*";
